# .github/workflows/ingest.yml  (GitHub Actions reads cron in UTC)
# on:
#   schedule:
#     - cron: '0 * * * *'   # ingest
#     - cron: '15 */3 * * *'   # refresh the API view

# minutes after midnight when a cron string fires (minute + hour fields)
cron_runs = function(cron) {
  f = strsplit(cron, " ")[[1]]
  field = function(x, n) {
    if (x == "*") return(0:(n - 1))
    if (startsWith(x, "*/")) return(seq(0, n - 1, by = as.integer(substring(x, 3))))
    as.integer(strsplit(x, ",")[[1]])
  }
  sort(as.vector(outer(field(f[1], 60), field(f[2], 24) * 60, `+`)))
}

ingest = function(table, batch) {
  rows_upsert(table, batch, by = c("aqs_id_full", "datetime"))   # idempotent
}

runs = cron_runs("0 * * * *")
refreshes = cron_runs("15 */3 * * *")
events = bind_rows(tibble(t = runs, job = "ingest"), tibble(t = refreshes, job = "refresh")) %>%
  arrange(t, job)

table = feed[0, ]
watermark = -1       # last minute safely loaded
served = NA          # newest reading the API view can see
served_at_18 = NA
worst = 0           # worst staleness seen at any run, over the day
for (i in seq_len(nrow(events))) {
  t = events$t[i]
  if (!is.na(served)) worst = max(worst, t - served)   # how old the API is just before this run
  if (events$job[i] == "ingest") {
    batch = feed %>% filter(minute > watermark, minute <= t)
    table = ingest(table, batch)
    watermark = t
  } else {
    served = if (nrow(table) > 0) max(table$minute) else NA
  }
  if (t <= 18 * 60) served_at_18 = served
}

tibble(
  ingest_runs   = length(runs),
  rows_in_table = nrow(table),
  duplicate_rows = nrow(table) - nrow(distinct(table, aqs_id_full, datetime)),
  freshness_min = 18 * 60 - served_at_18,     # API staleness at 18:00
  worst_staleness_min = worst,               # worst API staleness over the day
  next_refresh  = sprintf("%02d:%02d", min(refreshes[refreshes > 600]) %/% 60, min(refreshes[refreshes > 600]) %% 60)
)

