-- pg_cron: the database runs its own clock (times in UTC)
SELECT cron.schedule('ingest-air', '0 * * * *', $$CALL ingest_air()$$);
SELECT cron.schedule('refresh-api', '15 */3 * * *',
  $$REFRESH MATERIALIZED VIEW CONCURRENTLY api_latest$$);

-- inside ingest_air(): load the batch staged since the watermark
INSERT INTO readings (aqs_id_full, datetime, value)
SELECT aqs_id_full, datetime, value FROM staging
ON CONFLICT (aqs_id_full, datetime)
  DO UPDATE SET value = EXCLUDED.value;   -- upsert: a rerun is a no-op

-- next 5 runs: SELECT jobname, schedule FROM cron.job;

